/**
 * `motionary/native` (= `motionary/components/native`, 9.8) — native 2.0:
 * take the motion you designed on the web to React Native and Flutter.
 *
 * - `toReactNative(rules, { name })` — a React Native component (Animated +
 *   Easing.bezier / spring) for the entrance and press rules of a motion
 *   string.
 * - `toFlutter(rules, { name })` — a Flutter widget (AnimationController +
 *   Cubic curves) for the same rules.
 * - `nativeEasing(easing, 'react-native' | 'flutter')` — a CSS easing as
 *   `Easing.bezier(…)` / `Cubic(…)`.
 * - `nativeTokens()` — Motionary's motion tokens (durations, easings as
 *   bezier arrays, springs) as JSON for native design systems.
 *
 * Complete sample apps live in `examples/native/react-native` and
 * `examples/native/flutter`.
 */
import { parseMotion, type MotionRule } from '../dsl/index';
import { easingPoints } from '../design/index';
import { MOTION_TOKENS } from '../tokens/index';

type Platform = 'react-native' | 'flutter';
const NAMED: Record<string, string> = { spring: 'cubic-bezier(0.34, 1.56, 0.64, 1)', smooth: 'cubic-bezier(0.22, 1, 0.36, 1)' };
/** A CSS easing as React Native `Easing.bezier(…)` or Flutter `Cubic(…)` (9.8). */
export function nativeEasing(easing: string | undefined, platform: Platform): string {
  const p = easingPoints(NAMED[easing || ''] || easing || 'cubic-bezier(0.22, 1, 0.36, 1)');
  return platform === 'flutter' ? `Cubic(${p.join(', ')})` : `Easing.bezier(${p.join(', ')})`;
}

/** Start values for an entrance preset: opacity, translate x / y (dp), scale (9.8). */
export function entranceFrom(effect: string): { opacity: number; x: number; y: number; scale: number } {
  const m: Record<string, [number, number, number]> = { 'fade-up': [0, 24, 1], 'fade-down': [0, -24, 1], 'fade-left': [24, 0, 1], 'fade-right': [-24, 0, 1], scale: [0, 0, 0.85], 'zoom-in': [0, 0, 0.6], 'zoom-out': [0, 0, 1.2] };
  const [x, y, s] = m[effect] || [0, 0, 1];
  return { opacity: 0, x, y, scale: s };
}

const ident = (s: string) => s.replace(/(^|[-_\s]+)([a-z0-9])/gi, (_, __, c) => c.toUpperCase()).replace(/[^A-Za-z0-9]/g, '') || 'Motion';
const rulesOf = (r: string | MotionRule[]) => (typeof r === 'string' ? parseMotion(r).rules : r);

/** A React Native component for a motion string (entrance on mount, `pop` / press rules on press) (9.8). */
export function toReactNative(rules: string | MotionRule[], opts: { name?: string } = {}): string {
  const rs = rulesOf(rules);
  const name = ident(opts.name || 'MotionView');
  const enter = rs.find((r) => r.trigger === 'enter' || r.trigger === 'load');
  const press = rs.find((r) => r.trigger === 'click' || r.trigger === 'hover');
  const f = entranceFrom(enter?.effect || 'fade');
  const lines = [
    `// Generated by motionary/native (9.8) from: ${rs.map((r) => `${r.trigger}: ${r.effect}`).join('; ') || '—'}`,
    `import React, { useEffect, useRef } from 'react';`,
    `import { Animated, Easing, ${press ? 'Pressable, ' : ''}AccessibilityInfo } from 'react-native';`,
    ``,
    `export function ${name}({ children, index = 0, onPress }) {`,
    `  const t = useRef(new Animated.Value(0)).current;`,
    `  const s = useRef(new Animated.Value(1)).current;`,
    `  useEffect(() => {`,
    `    AccessibilityInfo.isReduceMotionEnabled().then((reduce) => {`,
    `      if (reduce) return t.setValue(1);`,
    `      Animated.timing(t, { toValue: 1, duration: ${enter?.duration ?? 600}, delay: ${enter?.delay ?? 0} + index * ${enter?.stagger ?? 0}, easing: ${nativeEasing(enter?.easing, 'react-native')}, useNativeDriver: true }).start();`,
    `    });`,
    `  }, []);`,
    `  const style = {`,
    `    opacity: t.interpolate({ inputRange: [0, 1], outputRange: [${f.opacity}, 1] }),`,
    `    transform: [`,
    `      { translateX: t.interpolate({ inputRange: [0, 1], outputRange: [${f.x}, 0] }) },`,
    `      { translateY: t.interpolate({ inputRange: [0, 1], outputRange: [${f.y}, 0] }) },`,
    `      { scale: Animated.multiply(s, t.interpolate({ inputRange: [0, 1], outputRange: [${f.scale}, 1] })) },`,
    `    ],`,
    `  };`,
  ];
  if (press) {
    lines.push(
      `  const pressIn = () => Animated.spring(s, { toValue: 0.92, stiffness: ${MOTION_TOKENS.spring.snappy.stiffness}, damping: ${MOTION_TOKENS.spring.snappy.damping}, useNativeDriver: true }).start();`,
      `  const pressOut = () => Animated.spring(s, { toValue: 1, stiffness: ${MOTION_TOKENS.spring.bouncy.stiffness}, damping: ${MOTION_TOKENS.spring.bouncy.damping}, useNativeDriver: true }).start();`,
      `  return (`,
      `    <Pressable onPressIn={pressIn} onPressOut={pressOut} onPress={onPress}>`,
      `      <Animated.View style={style}>{children}</Animated.View>`,
      `    </Pressable>`,
      `  );`
    );
  } else lines.push(`  return <Animated.View style={style}>{children}</Animated.View>;`);
  lines.push(`}`, ``);
  return lines.join('\n');
}

/** A Flutter widget for a motion string (entrance on first build, press spring) (9.8). */
export function toFlutter(rules: string | MotionRule[], opts: { name?: string } = {}): string {
  const rs = rulesOf(rules);
  const name = ident(opts.name || 'MotionView');
  const enter = rs.find((r) => r.trigger === 'enter' || r.trigger === 'load');
  const press = rs.some((r) => r.trigger === 'click' || r.trigger === 'hover');
  const f = entranceFrom(enter?.effect || 'fade');
  return [
    `// Generated by motionary/native (9.8) from: ${rs.map((r) => `${r.trigger}: ${r.effect}`).join('; ') || '—'}`,
    `import 'package:flutter/material.dart';`,
    ``,
    `class ${name} extends StatefulWidget {`,
    `  const ${name}({super.key, required this.child, this.index = 0, this.onTap});`,
    `  final Widget child;`,
    `  final int index;`,
    `  final VoidCallback? onTap;`,
    `  @override`,
    `  State<${name}> createState() => _${name}State();`,
    `}`,
    ``,
    `class _${name}State extends State<${name}> with SingleTickerProviderStateMixin {`,
    `  late final AnimationController _c = AnimationController(vsync: this, duration: const Duration(milliseconds: ${enter?.duration ?? 600}));`,
    `  late final Animation<double> _t = CurvedAnimation(parent: _c, curve: const ${nativeEasing(enter?.easing, 'flutter')});`,
    `  double _scale = 1;`,
    ``,
    `  @override`,
    `  void didChangeDependencies() {`,
    `    super.didChangeDependencies();`,
    `    if (MediaQuery.of(context).disableAnimations) { _c.value = 1; return; }`,
    `    Future.delayed(Duration(milliseconds: ${enter?.delay ?? 0} + widget.index * ${enter?.stagger ?? 0}), () { if (mounted) _c.forward(); });`,
    `  }`,
    ``,
    `  @override`,
    `  void dispose() { _c.dispose(); super.dispose(); }`,
    ``,
    `  @override`,
    `  Widget build(BuildContext context) {`,
    `    Widget w = AnimatedBuilder(`,
    `      animation: _t,`,
    `      builder: (context, child) => Opacity(`,
    `        opacity: ${f.opacity} + (1 - ${f.opacity}) * _t.value,`,
    `        child: Transform.translate(`,
    `          offset: Offset(${f.x} * (1 - _t.value), ${f.y} * (1 - _t.value)),`,
    `          child: Transform.scale(scale: ${f.scale} + (1 - ${f.scale}) * _t.value, child: child),`,
    `        ),`,
    `      ),`,
    `      child: widget.child,`,
    `    );`,
    press
      ? `    return GestureDetector(\n      onTapDown: (_) => setState(() => _scale = 0.92),\n      onTapUp: (_) => setState(() => _scale = 1),\n      onTapCancel: () => setState(() => _scale = 1),\n      onTap: widget.onTap,\n      child: AnimatedScale(scale: _scale, duration: const Duration(milliseconds: 180), curve: Curves.easeOutBack, child: w),\n    );`
      : `    return w;`,
    `  }`,
    `}`,
    ``,
  ].join('\n');
}

/** Motion tokens for native design systems: durations (ms), easings as bezier arrays, springs (9.8). */
export function nativeTokens(): { duration: Record<string, number>; easing: Record<string, number[]>; spring: Record<string, { stiffness: number; damping: number; mass: number }> } {
  const easing: Record<string, number[]> = {};
  for (const [k, v] of Object.entries(MOTION_TOKENS.easing)) easing[k] = easingPoints(v);
  return { duration: { ...MOTION_TOKENS.duration }, easing, spring: JSON.parse(JSON.stringify(MOTION_TOKENS.spring)) };
}
